package rag;

import rag.runtime.*;
import com.google.gson.*;
import ai.ConsultationBehaviorTest;
import ai.dto.*;
import ai.consultation.*;
import ai.session.ChatSessionData;
import ai.exception.AIException;
import java.util.*;
import java.time.Instant;
import java.io.IOException;

/** Synthetic keys, injected transports only. No environment credentials or network calls. */
public final class RagPhase4RuntimeTest {
    public interface Case {void run()throws Exception;}
    static int passed;
    public static void check(boolean v,String message){if(!v)throw new AssertionError(message);}
    public static void test(String name,Case c)throws Exception{c.run();passed++;System.out.println("PASS Phase4-offline "+name);}
    public static void rejected(Case c)throws Exception{try{c.run();}catch(IllegalArgumentException|RagException|AIException expected){return;}throw new AssertionError("Request should be blocked");}
    public static Map<String,String> environment(){Map<String,String> e=new HashMap<>();e.put("RAG_RUNTIME_MODE","LOCAL_GEMINI");e.put("RAG_ENVIRONMENT","test");e.put("RAG_ENABLED","false");e.put("RAG_DATABASE_APPROVED","true");e.put("RAG_LOCAL_GEMINI_AUTHORIZED","true");e.put("DB_HOST","127.0.0.1");e.put("DB_PORT","5432");e.put("DB_NAME","fpt_rag_test");e.put("DB_USER","synthetic-test-user");e.put("DB_PASSWORD","synthetic-test-password");e.put("RAG_EMBEDDING_API_KEY","synthetic-embedding-key");e.put("RAG_CHAT_TEST_API_KEY","synthetic-chat-key");e.put("GEMINI_API_KEY","synthetic-production-sentinel");return e;}
    public static JsonObject plan(){
        JsonObject p=new JsonObject();p.addProperty("planId","phase4-offline-"+UUID.randomUUID().toString());
        for(String b:Arrays.asList("approved","projectModelsVerified","restConfigurationVerified","quotaVerified","pricingVerified"))p.addProperty(b,true);
        p.addProperty("embeddingTier","Free Tier");p.addProperty("chatTier","Free Tier");p.addProperty("embeddingModel","gemini-embedding-001");p.addProperty("dimensions",768);p.addProperty("chatModel","gemini-3.8-flash");p.addProperty("thinkingLevel","medium");p.addProperty("backupModel","gemini-3.5-flash-lite");p.addProperty("backupThinkingLevel","low");p.addProperty("backupEnabled",false);
        long now=Instant.now().getEpochSecond();p.addProperty("verifiedAtEpochSeconds",now);p.addProperty("expiresAtEpochSeconds",now+900);
        String project="offline_"+UUID.randomUUID().toString().replace("-","");p.addProperty("embeddingProjectAlias",project);p.addProperty("chatProjectAlias",project);
        p.addProperty("maxRequests",4);p.addProperty("documentRequests",1);p.addProperty("queryRequests",2);p.addProperty("chatRequests",1);
        p.addProperty("requestsPerMinute",10);p.addProperty("requestsPerDay",100);p.addProperty("tokensPerMinute",30000);p.addProperty("tokensPerDay",100000);p.addProperty("maxChatOutputTokens",1200);
        p.addProperty("embeddingRequestsRemaining",100);p.addProperty("chatRequestsRemaining",100);p.addProperty("embeddingTokensRemaining",30000);p.addProperty("chatTokensRemaining",30000);
        for(String a:Arrays.asList("documentPayloadHashes","queryPayloadHashes","questions","documents"))p.add(a,new JsonArray());return p;
    }
    public static void allow(JsonObject plan,String title,String text,String group){GeminiEmbeddingService s=new GeminiEmbeddingService(new RagConfig(true,true,true,"gemini-embedding-001",768),"synthetic");JsonObject body=s.requestBody(title,text,group.equals("DOCUMENT")?"RETRIEVAL_DOCUMENT":"RETRIEVAL_QUERY");plan.getAsJsonArray(group.equals("DOCUMENT")?"documentPayloadHashes":"queryPayloadHashes").add(VectorValues.hash(body.toString()));}
    public static String vector(int n){JsonObject r=new JsonObject(),e=new JsonObject();JsonArray a=new JsonArray();for(int i=0;i<n;i++)a.add(i==0?2:0);e.add("values",a);r.add("embedding",e);return r.toString();}
    public static final class Ledger implements ApiRequestLedger {
        public int reserved,finished;public String group,state,error;public int status;
        public UUID reserve(String g,String op,String model,int tokens){reserved++;group=g;return UUID.randomUUID();}
        public void finish(UUID id,String st,int http,String err,long ms,Integer input,Integer output,Integer total){finished++;state=st;status=http;error=err;}
    }
    public static ChatOptions options(){ChatOptions o=new ChatOptions(.3,1200);o.setThinkingLevel("medium");o.setResponseSchema(ConsultationPrompt.schema());o.setMaxProviderAttempts(1);return o;}
    public static List<ChatMessage> messages(String q){return Arrays.asList(ChatMessage.system("Tư vấn bằng tiếng Việt."),ChatMessage.user("Dữ liệu tham khảo\nCâu hỏi của khách:\n"+q));}
    public static void main(String[] args)throws Exception{
        for(String mode:Arrays.asList("OFFLINE_MOCK","STAGING","PRODUCTION"))test("reject live mode "+mode,()->{Map<String,String> e=environment();e.put("RAG_RUNTIME_MODE",mode);rejected(()->new GeminiRuntimeConfig(e,plan()));});
        for(String field:Arrays.asList("RAG_EMBEDDING_API_KEY","RAG_CHAT_TEST_API_KEY","RAG_LOCAL_GEMINI_AUTHORIZED","RAG_DATABASE_APPROVED"))test("missing "+field+" never falls back",()->{Map<String,String> e=environment();e.remove(field);rejected(()->new GeminiRuntimeConfig(e,plan()));});
        for(String field:Arrays.asList("approved","quotaVerified","pricingVerified","projectModelsVerified","restConfigurationVerified"))test("reject unverified "+field,()->{JsonObject p=plan();p.addProperty(field,false);rejected(()->new GeminiRuntimeConfig(environment(),p));});
        test("reject string approval",()->{JsonObject p=plan();p.addProperty("approved","true");rejected(()->new GeminiRuntimeConfig(environment(),p));});
        test("reject production host",()->{Map<String,String> e=environment();e.put("DB_HOST","production.invalid");rejected(()->new GeminiRuntimeConfig(e,plan()));});
        test("reject wrong DB",()->{Map<String,String> e=environment();e.put("DB_NAME","postgres");rejected(()->new GeminiRuntimeConfig(e,plan()));});
        test("reject enabled production RAG",()->{Map<String,String> e=environment();e.put("RAG_ENABLED","true");rejected(()->new GeminiRuntimeConfig(e,plan()));});
        test("reject stale quota",()->{JsonObject p=plan();p.addProperty("verifiedAtEpochSeconds",Instant.now().getEpochSecond()-4000);rejected(()->new GeminiRuntimeConfig(environment(),p));});
        test("reject paid tier",()->{JsonObject p=plan();p.addProperty("chatTier","Paid Tier");rejected(()->new GeminiRuntimeConfig(environment(),p));});
        test("reject changed dimensions",()->{JsonObject p=plan();p.addProperty("dimensions",3072);rejected(()->new GeminiRuntimeConfig(environment(),p));});
        test("reject auto model replacement",()->{JsonObject p=plan();p.addProperty("chatModel","other-model");rejected(()->new GeminiRuntimeConfig(environment(),p));});
        test("reject insufficient quota",()->{JsonObject p=plan();p.addProperty("chatRequestsRemaining",0);rejected(()->new GeminiRuntimeConfig(environment(),p));});
        test("reject missing payload allowlist",()->{JsonObject p=plan();p.remove("queryPayloadHashes");rejected(()->new GeminiRuntimeConfig(environment(),p));});
        test("reject backup without access",()->{JsonObject p=plan();p.addProperty("backupEnabled",true);rejected(()->new GeminiRuntimeConfig(environment(),p));});
        for(String group:Arrays.asList("DOCUMENT","QUERY"))test("one POST "+group+" explicit 768 and L2",()->{
            JsonObject p=plan();String title=group.equals("DOCUMENT")?"Hướng dẫn WiFi":null,text="Kiểm tra nguồn điện modem.";allow(p,title,text,group);Ledger l=new Ledger();int[] calls={0};
            EmbeddingService s=new RuntimeEmbeddingService(new GeminiRuntimeConfig(environment(),p),l,(method,url,key,body,deadline)->{calls[0]++;check(l.reserved==1,"reserve before wire");check("POST".equals(method)&&url.endsWith(":embedContent")&&!url.contains("key="),"endpoint");check(key.equals("synthetic-embedding-key"),"test key only");check(body.get("outputDimensionality").getAsInt()==768&&!body.has("embedContentConfig"),"top-level dimension");check(body.get("taskType").getAsString().equals(group.equals("DOCUMENT")?"RETRIEVAL_DOCUMENT":"RETRIEVAL_QUERY"),"task");return new GeminiEmbeddingService.Result(200,vector(768));});
            float[] v=group.equals("DOCUMENT")?s.document(title,text):s.query(text);check(v.length==768&&v[0]==1f&&calls[0]==1&&l.finished==1&&l.state.equals("COMPLETED")&&s.providerKind().equals("GEMINI"),"valid normalized vector");
        });
        for(int status:new int[]{400,401,403,429,500,302})test("HTTP "+status+" consumes slot without retry",()->{JsonObject p=plan();allow(p,null,"WiFi yếu","QUERY");Ledger l=new Ledger();int[] calls={0};RuntimeEmbeddingService s=new RuntimeEmbeddingService(new GeminiRuntimeConfig(environment(),p),l,(a,b,c,d,e)->{calls[0]++;return new GeminiEmbeddingService.Result(status,"not logged");});rejected(()->s.query("WiFi yếu"));check(calls[0]==1&&l.reserved==1&&l.status==status&&l.state.equals("FAILED"),"no retry / redirect");});
        for(String response:Arrays.asList(vector(3072),"{}","{\"embedding\":{\"values\":[]}}"))test("invalid embedding rejected",()->{JsonObject p=plan();allow(p,null,"WiFi yếu","QUERY");Ledger l=new Ledger();RuntimeEmbeddingService s=new RuntimeEmbeddingService(new GeminiRuntimeConfig(environment(),p),l,(a,b,c,d,e)->new GeminiEmbeddingService.Result(200,response));rejected(()->s.query("WiFi yếu"));check(l.state.equals("FAILED")&&l.error.equals("INVALID_VECTOR"),"invalid dimensions");});
        test("network failure recorded uncertain no retry",()->{JsonObject p=plan();allow(p,null,"WiFi yếu","QUERY");Ledger l=new Ledger();int[] calls={0};RuntimeEmbeddingService s=new RuntimeEmbeddingService(new GeminiRuntimeConfig(environment(),p),l,(a,b,c,d,e)->{calls[0]++;throw new IOException("synthetic-secret-in-error");});rejected(()->s.query("WiFi yếu"));check(calls[0]==1&&l.state.equals("UNCERTAIN")&&!l.error.contains("secret"),"sanitized uncertain");});
        test("unapproved payload never reaches ledger or wire",()->{Ledger l=new Ledger();RuntimeEmbeddingService s=new RuntimeEmbeddingService(new GeminiRuntimeConfig(environment(),plan()),l,(a,b,c,d,e)->{throw new AssertionError("wire forbidden");});rejected(()->s.query("not in plan"));check(l.reserved==0,"no reserve");});
        test("Chat primary uses only test key medium schema",()->{JsonObject p=plan();p.getAsJsonArray("questions").add("Bạn hỗ trợ được gì?");Ledger l=new Ledger();ConsultationBehaviorTest.MockProvider wire=new ConsultationBehaviorTest.MockProvider(){public synchronized ChatResponse chat(List<ChatMessage> m,String k,String model,String b,ChatOptions o)throws AIException{check(k.equals("synthetic-chat-key"),"key");return super.chat(m,k,model,b,o);}};RuntimeGeminiProvider provider=new RuntimeGeminiProvider(new GeminiRuntimeConfig(environment(),p),l,wire);provider.chat(messages("Bạn hỗ trợ được gì?"),"synthetic-chat-key","gemini-3.8-flash",null,options());check(wire.calls==1&&l.group.equals("CHAT")&&wire.lastOptions.getThinkingLevel().equals("medium"),"one Chat request");rejected(()->provider.chat(messages("Bạn hỗ trợ được gì?"),"synthetic-production-sentinel","gemini-3.8-flash",null,options()));rejected(()->provider.chat(messages("Bạn hỗ trợ được gì?"),"synthetic-chat-key","gemini-3.5-flash-lite",null,options()));rejected(()->provider.listModels("",""));check(wire.calls==1,"blocked extra routes");});
        for(String kind:Arrays.asList("malformed","truncated"))test("Chat "+kind+" validated no repair request",()->{JsonObject p=plan();String q="Bạn hỗ trợ được những gì vậy?";p.getAsJsonArray("questions").add(q);Ledger l=new Ledger();ConsultationBehaviorTest.MockProvider wire=new ConsultationBehaviorTest.MockProvider();wire.outputs.add(ConsultationBehaviorTest.raw(kind.equals("malformed")?"State Tracking: No":"{",kind.equals("truncated")?"MAX_TOKENS":"STOP"));RuntimeGeminiProvider provider=new RuntimeGeminiProvider(new GeminiRuntimeConfig(environment(),p),l,wire);ChatOptions o=options();ChatResponse r=new ConsultationEngine().chat(q,new ChatSessionData(kind),ConsultationBehaviorTest.CATALOG,new ConsultationEngine.Target(provider,"synthetic-chat-key","gemini-3.8-flash",null,"medium",1200),null,o);check(wire.calls==1&&r.getProvider().equals("safe-fallback")&&!r.getContent().contains("State Tracking"),"safe output and one attempt");});
        test("Chat failure sanitized no implicit fallback",()->{JsonObject p=plan();p.getAsJsonArray("questions").add("WiFi yếu");Ledger l=new Ledger();ConsultationBehaviorTest.MockProvider wire=new ConsultationBehaviorTest.MockProvider();wire.outputs.add(new AIException(AIException.ErrorType.QUOTA_EXCEEDED,429,"secret-in-provider-error","Gemini"));RuntimeGeminiProvider provider=new RuntimeGeminiProvider(new GeminiRuntimeConfig(environment(),p),l,wire);try{provider.chat(messages("WiFi yếu"),"synthetic-chat-key","gemini-3.8-flash",null,options());throw new AssertionError();}catch(AIException e){check(!e.getMessage().contains("secret")&&wire.calls==1&&l.state.equals("FAILED"),"sanitized");}});
        test("explicit backup uses same test key low thinking bounded attempts",()->{JsonObject p=plan();p.addProperty("backupEnabled",true);p.addProperty("backupProjectModelVerified",true);p.addProperty("chatRequests",2);p.addProperty("maxRequests",5);String q="Bạn hỗ trợ được những gì vậy?";p.getAsJsonArray("questions").add(q);Ledger l=new Ledger();ConsultationBehaviorTest.MockProvider wire=new ConsultationBehaviorTest.MockProvider();wire.outputs.add(new AIException(AIException.ErrorType.QUOTA_EXCEEDED,429,"synthetic","Gemini"));RuntimeGeminiProvider provider=new RuntimeGeminiProvider(new GeminiRuntimeConfig(environment(),p),l,wire);ChatOptions o=options();o.setMaxProviderAttempts(2);ChatResponse result=new ConsultationEngine().chat(q,new ChatSessionData("backup"),ConsultationBehaviorTest.CATALOG,new ConsultationEngine.Target(provider,"synthetic-chat-key","gemini-3.8-flash",null,"medium",1200),new ConsultationEngine.Target(provider,"synthetic-chat-key","gemini-3.5-flash-lite",null,"low",1200),o);check(wire.calls==2&&l.reserved==2&&result.isUsedFallbackModel()&&wire.lastOptions.getThinkingLevel().equals("low"),"controlled backup");});
        test("embedding conservative input bound rejects before wire",()->{StringBuilder text=new StringBuilder();for(int i=0;i<800;i++)text.append('ề');JsonObject p=plan();allow(p,null,text.toString(),"QUERY");Ledger l=new Ledger();RuntimeEmbeddingService s=new RuntimeEmbeddingService(new GeminiRuntimeConfig(environment(),p),l,(a,b,c,d,e)->{throw new AssertionError("oversized input wire");});rejected(()->s.query(text.toString()));check(l.reserved==0,"input bound before cost gate");});
        test("embedding usage over bound blocks future execution",()->{JsonObject p=plan();allow(p,null,"WiFi yếu","QUERY");Ledger l=new Ledger();JsonObject result=JsonParser.parseString(vector(768)).getAsJsonObject(),usage=new JsonObject();usage.addProperty("promptTokenCount",999999);result.add("usageMetadata",usage);RuntimeEmbeddingService s=new RuntimeEmbeddingService(new GeminiRuntimeConfig(environment(),p),l,(a,b,c,d,e)->new GeminiEmbeddingService.Result(200,result.toString()));rejected(()->s.query("WiFi yếu"));check(l.state.equals("UNCERTAIN")&&l.error.equals("TOKEN_BOUND"),"overspend uncertainty");});
        test("zero vector rejected without truncation or extra request",()->{JsonObject p=plan();allow(p,null,"WiFi yếu","QUERY");Ledger l=new Ledger();RuntimeEmbeddingService s=new RuntimeEmbeddingService(new GeminiRuntimeConfig(environment(),p),l,(a,b,c,d,e)->new GeminiEmbeddingService.Result(200,vector(768).replace("2,","0,")));rejected(()->s.query("WiFi yếu"));check(l.finished==1&&l.state.equals("FAILED"),"zero norm");});
        test("Chat usage integer overflow rejected",()->{JsonObject p=plan();p.getAsJsonArray("questions").add("WiFi yếu");Ledger l=new Ledger();ConsultationBehaviorTest.MockProvider wire=new ConsultationBehaviorTest.MockProvider();ChatResponse invalid=ConsultationBehaviorTest.envelope("Dạ em hỗ trợ nhé.");invalid.setCompletionTokens(Integer.MAX_VALUE);invalid.setThoughtsTokens(1);wire.outputs.add(invalid);RuntimeGeminiProvider provider=new RuntimeGeminiProvider(new GeminiRuntimeConfig(environment(),p),l,wire);rejected(()->provider.chat(messages("WiFi yếu"),"synthetic-chat-key","gemini-3.8-flash",null,options()));check(l.state.equals("UNCERTAIN")&&wire.calls==1,"token overflow bound");});
        test("malformed embedding usage cannot escape delegate parsing",()->{JsonObject p=plan();allow(p,null,"WiFi yếu","QUERY");Ledger l=new Ledger();JsonObject result=JsonParser.parseString(vector(768)).getAsJsonObject(),usage=new JsonObject();usage.addProperty("promptTokenCount","not-a-number");result.add("usageMetadata",usage);RuntimeEmbeddingService s=new RuntimeEmbeddingService(new GeminiRuntimeConfig(environment(),p),l,(a,b,c,d,e)->new GeminiEmbeddingService.Result(200,result.toString()));rejected(()->s.query("WiFi yếu"));check(l.state.equals("FAILED"),"invalid usage bypassed outer adapter");});
        System.out.println("Phase4 offline: "+passed+" passed; real API requests=0");
    }
}
